C1.raw_latex:
\label{clmmeasurables}
 Suppose that $\aleph_0<\kappa<\lambda$ and both $\kappa$ and $\lambda$ are measurable.
 Then ${\rm Gal}(\mathscr{U},\lambda,\lambda)$ holds whenever $\mathscr{U}$ is a normal ultrafilter over $\kappa$.

C2.raw_latex:
\label{clmpreservation}
 Let $V$ be a model of $\mathsf{AD}$ and let $G\subseteq\mathbb{M}_{\aleph_1\aleph_2}$ be $V$-generic.
 Then $\aleph_1$ is measurable in $V[G]$ and $\mathscr{D}_{\aleph_1}$ is an ultrafilter.

C3.raw_latex:
\label{clmsamecof}
\begin{enumerate}
  \item [$(a)$] If $\kappa={\rm cf(\lambda)$ then $\binom{\lambda}{\kappa}\nrightarrow\binom{\lambda}{\kappa}$.
  \item [$(b)$] If ${\rm Gal}(\mathscr{D}_\kappa,\lambda,\lambda)$ holds then $\binom{\lambda}{\kappa}\rightarrow\binom{\lambda}{\kappa}$.
  \item [$(c)$] If $\kappa={\rm cf(\lambda)$ then $\neg{\rm Gal}(\mathscr{D}_\kappa,\lambda,\lambda)$.
\end{enumerate}

D2.raw_latex:
\label{deffgp}
 The full Galvin number. \newline
 Let $\mathfrak{fgp}$ be the first $\lambda$ for which every family $\mathcal{C}=\{C_\alpha:\alpha\in\lambda^+\}\subseteq\mathscr{D}_{\aleph_1}$ contains a subfamily $\mathcal{D}$ of size $\lambda^+$ such that $\bigcap\mathcal{D}\in\mathscr{D}_{\aleph_1}$.

D3.raw_latex:
\label{defmagidorlike} The forcing $\mathbb{M}_{\gamma\kappa}$. \newline
 Let $\kappa$ be regular and uncountable and assume that $\omega\leq\gamma<\kappa$.
 \begin{enumerate}
   \item [$(\aleph)$] A condition $p\in\mathbb{M}_{\gamma\kappa}$ is a pair $(s^p,A^p)$ such that $s^p\in[\kappa]^{<\gamma}, A^p\in[\kappa]^\kappa$ and $\bigcup{s^p}<\bigcap{A^p}$.
   \item [$(\beth)$] If $p,q\in\mathbb{M}_{\gamma\kappa}$ then $p\leq{q}$ iff $s^p\subseteq{s^q}, \langle{A^q}\rangle\subseteq\langle{A^p}\rangle$ and $s^q-s^p={}_\omega{t}$ for some $t\in[A]^{<\gamma}$.
 \end{enumerate}
